// the servant: an extension clause, resolved like a member call
extension (m: Movable)
  def moveTo(to: Position): Unit = m.setPosition(to)
  def moveBy(dx: Int, dy: Int): Unit = moveTo(m.position.shifted(dx, dy))

// Scala 2 equivalent: implicit class MoveOps(m: Movable) extends AnyVal { ... }
circle.moveTo(Position(3, 4))          // member syntax; the extension must be in scope

