object Moving {
  implicit class MoveOps(private val m: Movable) extends AnyVal {
    def moveTo(to: Position): Unit = m.setPosition(to)
  }
}

import Moving.MoveOps           // brings the behaviour into scope
circle.moveTo(Position(3, 4))   // compiled as Moving.MoveOps(circle).moveTo(...)
